import { Colorize, Cuboid, Hull, Rotate, Translate } from "jscad-fiber"
import { SmdChipLead } from "./SmdChipLead"

const PIN_METAL_COLOR = "#c0c0c0"

export const PinHeader = ({
  x,
  y,
  pinThickness,
  shortSidePinLength,
  longSidePinLength,
  bodyHeight,
  bodyLength = 2.54,
  bodyWidth = 2.54,
  flipZ,
  smd,
  rightangle,
}: {
  x: number
  y: number
  pinThickness: number
  shortSidePinLength: number
  longSidePinLength: number
  bodyHeight: number
  bodyLength?: number
  bodyWidth?: number
  flipZ: (z: number) => number
  smd?: boolean
  rightangle?: boolean
}) => {
  return (
    <>
      <Translate y={rightangle ? -3 : 0}>
        <Cuboid
          color="#222"
          size={[bodyLength, bodyWidth, bodyHeight]}
          center={[x, y, flipZ(bodyHeight / 2)]}
        />
      </Translate>
      <Colorize color={PIN_METAL_COLOR}>
        {smd ? (
          <SmdChipLead
            rotation={-Math.PI / 2}
            position={{
              x: x,
              y: y + 1,
              z: pinThickness / 2,
            }}
            thickness={pinThickness}
            width={pinThickness}
            height={pinThickness}
            padContactLength={2}
            bodyDistance={3}
          />
        ) : (
          <Hull>
            <Cuboid
              color={PIN_METAL_COLOR}
              size={[pinThickness, pinThickness, shortSidePinLength * 0.9]}
              center={[x, y, flipZ(bodyHeight * 0.9 + bodyHeight / 2)]}
            />
            <Cuboid
              color={PIN_METAL_COLOR}
              size={[
                pinThickness / 1.8,
                pinThickness / 1.8,
                shortSidePinLength,
              ]}
              center={[x, y, flipZ(bodyHeight + bodyHeight / 2)]}
            />
          </Hull>
        )}
      </Colorize>

      <Colorize color={PIN_METAL_COLOR}>
        <Translate y={rightangle ? -3.9 : 0} z={rightangle ? 1 : 0}>
          <Rotate rotation={rightangle ? [-Math.PI / 2, 0, 0] : [0, 0, 0]}>
            <Hull>
              <Cuboid
                color={PIN_METAL_COLOR}
                size={[pinThickness, pinThickness, longSidePinLength * 0.9]}
                center={[x, y, flipZ((-longSidePinLength / 2) * 0.9)]}
              />
              <Cuboid
                color={PIN_METAL_COLOR}
                size={[
                  pinThickness / 1.8,
                  pinThickness / 1.8,
                  longSidePinLength,
                ]}
                center={[x, y, flipZ(-longSidePinLength / 2)]}
              />
            </Hull>
          </Rotate>
        </Translate>
      </Colorize>
    </>
  )
}
